foreach (string word in words)
{
    if (freq.ContainsKey(word))
    {
        freq[word]++;
    }
    else
    {
        freq[word] = 1;
    }
}

var sorted = freq.OrderByDescending(kv => kv.Value)
                 .ThenBy(kv => kv.Key)
                 .ToList();

foreach (var kv in sorted)
{
