			Birthday:  birthdayStrFormatted,
			Age:       age,
			Relatives: relatives,
		}

		people = append(people, person)
	}

	// Output as JSON array
	jsonData, err := json.Marshal(people)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error marshaling JSON: %v\n", err)
		os.Exit(1)
	}

	fmt.Println(string(jsonData))
}
