for (int i = 2; i * i <= N; i++)
{
    if (!isComposite[i])
    {
        for (int j = i * i; j <= N; j += i)
        {
            isComposite[j] = true;
        }
    }
}

for (int i = 2; i <= N; i++)
{
    if (!isComposite[i])
    {
        Console.WriteLine(i);
    }
}
