    string[] words = line.Split(new char[] { ' ', ',', '.', ';', ':', '!', '?', '\'', '"', '(', ')', '[', ']', '{', '}', '\t', '\n', '\r' }, StringSplitOptions.RemoveEmptyEntries);

    foreach (string word in words)
    {
        string cleaned = new string(word.Where(char.IsLetter).ToArray()).ToLower();
