        if (wordCounts.ContainsKey(cleaned))
            wordCounts[cleaned]++;
        else
            wordCounts[cleaned] = 1;
    }
}

var sortedWords = wordCounts
    .OrderByDescending(kvp => kvp.Value)
    .ThenBy(kvp => kvp.Key);

foreach (var kvp in sortedWords)
{
    Console.WriteLine($"{kvp.Key}: {kvp.Value}");
