    if (parts.Length < 7) continue;

    string fullName = parts[0].Trim();
    string birthdayStr = parts[1].Trim();
    string fatherName = parts[3].Trim();
    string motherName = parts[4].Trim();
    string brotherName = parts[5].Trim();
