    // Ringo Starr -> FirstName: Ringo, LastName: Starr
    // George Harrison -> FirstName: George, LastName: Harrison

    string[] nameParts = fullName.Split(' ');
    string firstName = nameParts[0];
    string lastName = nameParts[nameParts.Length - 1];

